{
  "name": "@earendil-works/pi-coding-agent",
  "version": "0.0.0-pi-subagents-test-shim",
  "type": "module",
  "main": "./index.mjs",
  "types": "./dist/index.d.ts",
  "private": true,
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./index.mjs"
    }
  }
}

import assert from "node:assert/strict";
import * as os from "node:os";
import { describe, it } from "node:test";
import { createSubagentExecutor, unknownSubagentActionMessage } from "../../src/runs/foreground/subagent-executor.ts";
import type { SubagentState } from "../../src/shared/types.ts";

function createState(): SubagentState {
	return {
		baseCwd: "",
		currentSessionId: null,
		asyncJobs: new Map(),
		foregroundRuns: new Map(),
		foregroundControls: new Map(),
		lastForegroundControlId: null,
		pendingForegroundControlNotices: new Map(),
		cleanupTimers: new Map(),
		lastUiContext: null,
		poller: null,
		completionSeen: new Map(),
		watcher: null,
		watcherRestartTimer: null,
		resultFileCoalescer: { schedule: () => false, clear: () => {} },
	};
}

function createExecutor() {
	return createSubagentExecutor({
		pi: { events: { emit() {}, on() { return () => {}; } }, getSessionName() { return "parent"; } } as any,
		state: createState(),
		config: { maxSubagentDepth: 2, control: {}, intercomBridge: {} } as any,
		asyncByDefault: false,
		tempArtifactsDir: os.tmpdir(),
		getSubagentSessionRoot: () => os.tmpdir(),
		expandTilde: (value) => value,
		discoverAgents: () => ({ agents: [] }),
	});
}

function ctx() {
	return {
		cwd: os.tmpdir(),
		hasUI: false,
		sessionManager: { getSessionId() { return "session"; }, getSessionFile() { return null; } },
		modelRegistry: { getAvailable() { return []; } },
	} as any;
}

describe("subagent action recovery", () => {
	it("suggests a benign typo with safe next steps", () => {
		const message = unknownSubagentActionMessage("statsu");

		assert.match(message, /Unknown action: statsu\. Did you mean status\?/);
		assert.match(message, /Use subagent\(\{ action: "status" \}\)/);
		assert.match(message, /Valid: .*status/);
	});

	it("does not suggest a destructive near-miss", () => {
		const message = unknownSubagentActionMessage("del");

		assert.match(message, /Unknown action: del\./);
		assert.doesNotMatch(message, /Did you mean delete\?/);
		assert.match(message, /Valid: .*delete/);
	});

	it("returns a concise recovery error for an invalid action", async () => {
		const result = await createExecutor().execute("invalid-action", { action: "statsu" }, new AbortController().signal, undefined, ctx());
		assert.equal(result.isError, true);
		assert.equal(result.content[0]?.type, "text");
		assert.equal(result.content[0]?.text, unknownSubagentActionMessage("statsu"));
	});

	it("routes invalid schedule actions through common recovery", async () => {
		const result = await createExecutor().execute("invalid-schedule-action", { action: "schedule.lsit" }, new AbortController().signal, undefined, ctx());
		assert.equal(result.isError, true);
		assert.equal(result.content[0]?.type, "text");
		assert.equal(result.content[0]?.text, unknownSubagentActionMessage("schedule.lsit"));
	});

	it("lists and suggests mission decision resolution", () => {
		const message = unknownSubagentActionMessage("mission.resolve-decison");

		assert.match(message, /Did you mean mission\.resolve-decision\?/);
		assert.match(message, /Valid: .*mission\.resolve-decision/);
	});
});

import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { afterEach, beforeEach, describe, it } from "node:test";
import { registerAgent } from "../../src/api/agents.ts";
import { clearAgentDiscoveryCache, discoverAgentSnapshot, discoverAgents, discoverAgentsAll } from "../../src/agents/agents.ts";
import { mergeRuntimeAgents, clearRuntimeAgentsForPi } from "../../src/agents/runtime-agent-registry.ts";
import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

let tempRoot = "";
let home = "";
let project = "";
let pi: ExtensionAPI;
const previousEnv: Record<string, string | undefined> = {};
const managedEnv = ["HOME", "USERPROFILE", "PI_CODING_AGENT_DIR", "PI_SUBAGENT_EXTRA_AGENT_DIRS", "PI_OFFLINE"];

function writeAgent(filePath: string, name: string, description: string): void {
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, `---\nname: ${name}\ndescription: ${description}\n---\n\n${description}.\n`, "utf-8");
}

function writeJson(filePath: string, value: unknown): void {
	fs.mkdirSync(path.dirname(filePath), { recursive: true });
	fs.writeFileSync(filePath, JSON.stringify(value, null, 2), "utf-8");
}

function makePi(): ExtensionAPI {
	return { on() {}, registerTool() {} } as unknown as ExtensionAPI;
}

describe("agent discovery snapshots", () => {
	beforeEach(() => {
		tempRoot = fs.mkdtempSync(path.join(os.tmpdir(), "pi-agent-discovery-cache-"));
		home = path.join(tempRoot, "home");
		project = path.join(tempRoot, "project");
		for (const name of managedEnv) previousEnv[name] = process.env[name];
		process.env.HOME = home;
		process.env.USERPROFILE = home;
		process.env.PI_CODING_AGENT_DIR = path.join(home, ".pi", "agent");
		process.env.PI_OFFLINE = "true";
		delete process.env.PI_SUBAGENT_EXTRA_AGENT_DIRS;
		pi = makePi();
		clearAgentDiscoveryCache();
	});

	afterEach(() => {
		clearRuntimeAgentsForPi(pi);
		clearAgentDiscoveryCache();
		for (const name of managedEnv) {
			const value = previousEnv[name];
			if (value === undefined) delete process.env[name];
			else process.env[name] = value;
		}
		fs.rmSync(tempRoot, { recursive: true, force: true });
	});

	it("keeps effective and all-source projections distinct in one snapshot", () => {
		const userAgentPath = path.join(home, ".pi", "agent", "agents", "shared.md");
		const projectAgentPath = path.join(project, ".pi", "agents", "shared.md");
		writeAgent(userAgentPath, "shared", "User shared");
		writeAgent(projectAgentPath, "shared", "Project shared");
		writeAgent(path.join(home, ".pi", "agent", "agents", "scope-hidden.md"), "scope-hidden", "User hidden");
		writeJson(path.join(project, ".pi", "settings.json"), {
			subagents: { agentOverrides: { "scope-hidden": { disabled: true } } },
		});

		const snapshot = discoverAgentSnapshot(project, "both", undefined, { includeChains: false });
		assert.equal(snapshot.effective.agents.find((agent) => agent.name === "shared")?.source, "project");
		assert.equal(snapshot.effective.agents.some((agent) => agent.name === "scope-hidden"), false);
		assert.equal(snapshot.all.user.some((agent) => agent.name === "shared"), true);
		assert.equal(snapshot.all.project.some((agent) => agent.name === "shared"), true);
		assert.equal(snapshot.all.user.some((agent) => agent.name === "scope-hidden"), true);
		assert.equal(snapshot.all.project.some((agent) => agent.name === "scope-hidden"), false);
		assert.equal(snapshot.effective.directories.some((directory) => directory.source === "project"), true);
	});

	it("retains hidden definitions for runtime collision checks", () => {
		const hiddenPath = path.join(home, ".pi", "agent", "agents", "scope-hidden.md");
		writeAgent(hiddenPath, "scope-hidden", "User hidden");
		const registration = registerAgent({
			pi,
			name: "scope-hidden",
			definition: { description: "Runtime hidden collision", systemPrompt: "Runtime." },
		});
		try {
			const snapshot = discoverAgentSnapshot(project, "project", undefined, { includeChains: false });
			const configured = [...snapshot.all.builtin, ...snapshot.all.package, ...snapshot.all.user, ...snapshot.all.project];
			assert.equal(snapshot.effective.agents.some((agent) => agent.name === "scope-hidden"), false);
			assert.throws(
				() => mergeRuntimeAgents(pi, snapshot.effective, configured),
				/collides with configured agent 'scope-hidden'/,
			);
		} finally {
			registration.dispose();
		}
	});

	it("invalidates agent and chain projections when files change or appear", () => {
		const agentPath = path.join(project, ".pi", "agents", "fresh.md");
		const chainPath = path.join(project, ".pi", "chains", "fresh.chain.md");
		writeAgent(agentPath, "fresh", "Initial agent");
		fs.mkdirSync(path.dirname(chainPath), { recursive: true });
		fs.writeFileSync(chainPath, "---\nname: fresh-chain\ndescription: Initial chain\n---\n\n## fresh\nInspect\n", "utf-8");

		const first = discoverAgentSnapshot(project, "both");
		assert.equal(first.effective.agents.find((agent) => agent.name === "fresh")?.description, "Initial agent");
		assert.equal(first.all.chains.find((chain) => chain.name === "fresh-chain")?.description, "Initial chain");

		writeAgent(agentPath, "fresh", "Updated agent");
		fs.writeFileSync(chainPath, "---\nname: fresh-chain\ndescription: Updated chain\n---\n\n## fresh\nInspect\n", "utf-8");
		const updated = discoverAgentSnapshot(project, "both");
		assert.equal(updated.effective.agents.find((agent) => agent.name === "fresh")?.description, "Updated agent");
		assert.equal(updated.all.chains.find((chain) => chain.name === "fresh-chain")?.description, "Updated chain");

		fs.rmSync(agentPath);
		const addedPath = path.join(project, ".pi", "agents", "added.md");
		writeAgent(addedPath, "added", "Added agent");
		const changedFiles = discoverAgents(project, "both");
		assert.equal(changedFiles.agents.some((agent) => agent.name === "fresh"), false);
		assert.equal(changedFiles.agents.some((agent) => agent.name === "added"), true);
	});

	it("matches scoped discovery settings and precedence for user and project views", () => {
		writeAgent(path.join(home, ".pi", "agent", "agents", "shared.md"), "shared", "User shared");
		writeAgent(path.join(project, ".pi", "agents", "shared.md"), "shared", "Project shared");
		writeAgent(path.join(home, ".pi", "agent", "agents", "user-only.md"), "user-only", "User only");
		writeAgent(path.join(project, ".pi", "agents", "project-only.md"), "project-only", "Project only");
		writeJson(path.join(home, ".pi", "agent", "settings.json"), { subagents: { agentOverrides: { shared: { description: "User override" } } } });
		writeJson(path.join(project, ".pi", "settings.json"), { subagents: { agentOverrides: { shared: { description: "Project override" } } } });

		for (const scope of ["user", "project"] as const) {
			const direct = discoverAgents(project, scope);
			const snapshot = discoverAgentSnapshot(project, scope, undefined, { includeChains: false }).effective;
			assert.deepEqual(snapshot, direct);
		}
	});

	it("invalidates when a new agent appears in a previously inspected nested directory", () => {
		const nestedDir = path.join(project, ".pi", "agents", "nested");
		fs.mkdirSync(nestedDir, { recursive: true });

		const initial = discoverAgents(project, "both");
		assert.equal(initial.agents.some((agent) => agent.name === "nested-agent"), false);

		writeAgent(path.join(nestedDir, "nested-agent.md"), "nested-agent", "Nested agent");
		const updated = discoverAgents(project, "both");
		assert.equal(updated.agents.some((agent) => agent.name === "nested-agent"), true);
	});

	it("does not read out-of-scope user settings for a project snapshot", () => {
		writeAgent(path.join(project, ".pi", "agents", "project-agent.md"), "project-agent", "Project agent");
		const userSettingsPath = path.join(home, ".pi", "agent", "settings.json");
		fs.mkdirSync(path.dirname(userSettingsPath), { recursive: true });
		fs.writeFileSync(userSettingsPath, "{ malformed", "utf-8");

		const snapshot = discoverAgentSnapshot(project, "project", undefined, { includeChains: false });
		assert.equal(snapshot.effective.agents.some((agent) => agent.name === "project-agent"), true);
		assert.equal(snapshot.all.project.some((agent) => agent.name === "project-agent"), true);
	});

	it("keeps shared package agent metadata scoped to the selected settings source", () => {
		const userPackageRoot = path.join(tempRoot, "user-package");
		const projectPackageRoot = path.join(tempRoot, "project-package");
		const sharedAgentDir = path.join(tempRoot, "shared-package-agents");
		writeJson(path.join(home, ".pi", "agent", "settings.json"), { packages: [userPackageRoot] });
		writeJson(path.join(project, ".pi", "settings.json"), { packages: [projectPackageRoot] });
		writeJson(path.join(userPackageRoot, "package.json"), {
			name: "user-package",
			"pi-subagents": { agents: [path.relative(userPackageRoot, sharedAgentDir)] },
		});
		writeJson(path.join(projectPackageRoot, "package.json"), {
			name: "project-package",
			"pi-subagents": { agents: [path.relative(projectPackageRoot, sharedAgentDir)] },
		});
		writeAgent(path.join(sharedAgentDir, "shared.md"), "shared", "Shared package agent");

		const directUser = discoverAgents(project, "user").agents.find((agent) => agent.name === "shared");
		const directProject = discoverAgents(project, "project").agents.find((agent) => agent.name === "shared");
		const snapshotUser = discoverAgentSnapshot(project, "user", undefined, { includeChains: false }).effective.agents.find((agent) => agent.name === "shared");
		const snapshotProject = discoverAgentSnapshot(project, "project", undefined, { includeChains: false }).effective.agents.find((agent) => agent.name === "shared");

		assert.equal(directUser?.packageSourceName, "user-package");
		assert.equal(directProject?.packageSourceName, "project-package");
		assert.equal(snapshotUser?.packageSourceName, directUser?.packageSourceName);
		assert.equal(snapshotProject?.packageSourceName, directProject?.packageSourceName);
	});

	it("surfaces malformed in-scope settings while collecting package roots", () => {
		const settingsPath = path.join(home, ".pi", "agent", "settings.json");
		fs.mkdirSync(path.dirname(settingsPath), { recursive: true });
		fs.writeFileSync(settingsPath, "{ malformed", "utf-8");

		assert.throws(
			() => discoverAgentSnapshot(project, "both", undefined, { includeChains: false }),
			(error: unknown) => error instanceof Error
				&& error.message.includes(settingsPath)
				&& error.message.includes("Failed to parse settings file"),
		);
	});

	it("invalidates when project-root policy changes", () => {
		const outer = path.join(tempRoot, "outer");
		const nested = path.join(outer, "nested");
		fs.mkdirSync(path.join(outer, ".git"), { recursive: true });
		writeAgent(path.join(outer, ".pi", "agents", "outer.md"), "outer", "Outer agent");
		writeAgent(path.join(nested, ".pi", "agents", "nested.md"), "nested", "Nested agent");
		writeJson(path.join(nested, ".pi", "settings.json"), { subagents: { projectRootResolution: "git-root" } });

		const gitRoot = discoverAgents(nested, "both");
		assert.equal(gitRoot.projectAgentsDir, path.join(outer, ".pi", "agents"));
		assert.equal(gitRoot.agents.some((agent) => agent.name === "outer"), true);
		assert.equal(gitRoot.agents.some((agent) => agent.name === "nested"), false);

		writeJson(path.join(nested, ".pi", "settings.json"), { subagents: { projectRootResolution: "nearest" } });
		const nearest = discoverAgents(nested, "both");
		assert.equal(nearest.projectAgentsDir, path.join(nested, ".pi", "agents"));
		assert.equal(nearest.agents.some((agent) => agent.name === "nested"), true);
		assert.equal(nearest.agents.some((agent) => agent.name === "outer"), false);
	});

	it("does not parse chains on the ordinary effective discovery fast path", () => {
		const agentPath = path.join(project, ".pi", "agents", "worker.md");
		const chainPath = path.join(project, ".pi", "chains", "broken.chain.md");
		writeAgent(agentPath, "worker", "Worker");
		fs.mkdirSync(path.dirname(chainPath), { recursive: true });
		fs.writeFileSync(chainPath, "not a valid chain", "utf-8");

		assert.equal(discoverAgents(project, "both").agents.some((agent) => agent.name === "worker"), true);
		assert.equal(discoverAgentsAll(project).chainDiagnostics.some((diagnostic) => diagnostic.filePath === chainPath), true);
	});

	it("ignores project settings, agents and chains when the session declined project trust", () => {
		writeAgent(path.join(home, ".pi", "agent", "agents", "probe.md"), "probe", "User probe");
		writeJson(path.join(home, ".pi", "agent", "settings.json"), {
			subagents: { agentOverrides: { probe: { model: "openai/luna" } }, modelScope: { enforce: true, allow: ["openai/luna"] } },
		});
		writeAgent(path.join(project, ".pi", "agents", "project-only.md"), "project-only", "Project only");
		writeJson(path.join(project, ".pi", "settings.json"), {
			subagents: { agentOverrides: { probe: { model: "openai/astra" } }, modelScope: { enforce: true, allow: ["openai/astra"] } },
		});
		fs.mkdirSync(path.join(project, ".pi", "chains"), { recursive: true });
		fs.writeFileSync(path.join(project, ".pi", "chains", "project.chain.md"), "---\nname: project-chain\ndescription: Project chain\n---\n\n## probe\nInspect\n", "utf-8");
		// The repository's own package.json can declare agents too.
		writeJson(path.join(project, "package.json"), { name: "repo", "pi-subagents": { agents: ["./repo-agents"] } });
		writeAgent(path.join(project, "repo-agents", "repo-agent.md"), "repo-agent", "Repository agent");

		const untrusted = { projectTrusted: false };
		for (const discovered of [discoverAgents(project, "both", undefined, untrusted), discoverAgentSnapshot(project, "both", undefined, untrusted).effective]) {
			assert.equal(discovered.agents.find((agent) => agent.name === "probe")?.model, "openai/luna");
			assert.equal(discovered.agents.some((agent) => agent.name === "project-only"), false);
			assert.equal(discovered.agents.some((agent) => agent.name === "repo-agent"), false);
			assert.deepEqual(discovered.modelScope?.allow, ["openai/luna"]);
			assert.equal(discovered.directories.some((directory) => directory.source === "project" || directory.source === "package"), false);
		}
		const all = discoverAgentsAll(project, undefined, untrusted);
		assert.deepEqual(all.project, []);
		assert.deepEqual(all.package, []);
		assert.equal(all.user.find((agent) => agent.name === "probe")?.model, "openai/luna");
		assert.equal(all.chains.some((chain) => chain.name === "project-chain"), false);
		assert.throws(() => discoverAgents(project, "project", undefined, untrusted), /agentScope: "project" requires project trust/);
		assert.throws(() => discoverAgentSnapshot(project, "project", undefined, untrusted), /agentScope: "project" requires project trust/);
		assert.equal(discoverAgents(project, "user", undefined, untrusted).agents.some((agent) => agent.name === "repo-agent"), false);

		// Trusted lookups share the cached sources and still see the project.
		const trusted = discoverAgentSnapshot(project, "both");
		assert.equal(trusted.effective.agents.find((agent) => agent.name === "probe")?.model, "openai/astra");
		assert.equal(trusted.effective.agents.some((agent) => agent.name === "project-only"), true);
		assert.equal(trusted.effective.agents.some((agent) => agent.name === "repo-agent"), true);
		assert.equal(discoverAgents(project, "user").agents.some((agent) => agent.name === "repo-agent"), true);
		assert.deepEqual(trusted.effective.modelScope?.allow, ["openai/astra"]);
		assert.equal(trusted.all.chains.some((chain) => chain.name === "project-chain"), true);
		assert.equal(discoverAgents(project, "both", undefined, untrusted).agents.find((agent) => agent.name === "probe")?.model, "openai/luna");
	});

	it("reads nothing from project settings when the session declined project trust", () => {
		const userAgents = path.join(home, ".pi", "agent", "agents");
		writeAgent(path.join(userAgents, "probe.md"), "probe", "User probe");
		writeJson(path.join(home, ".pi", "agent", "settings.json"), { subagents: { agentOverrides: { probe: { model: "openai/luna" } } } });
		const projectSettings = path.join(project, ".pi", "settings.json");
		const untrusted = { projectTrusted: false };

		for (const content of ["{ not json", JSON.stringify({ subagents: { projectRootResolution: "bogus" } })]) {
			fs.mkdirSync(path.dirname(projectSettings), { recursive: true });
			fs.writeFileSync(projectSettings, content, "utf-8");
			clearAgentDiscoveryCache();
			assert.throws(() => discoverAgents(project, "both"), /settings/u, "a trusted lookup still reports the broken file");
			assert.equal(discoverAgents(project, "both", undefined, untrusted).agents.find((agent) => agent.name === "probe")?.model, "openai/luna");
			assert.equal(discoverAgentSnapshot(project, "both", undefined, untrusted).effective.agents.some((agent) => agent.name === "probe"), true);
			// Runtime-registered agents take their model settings from the same untrusted view.
			const registration = registerAgent({ pi, name: "runtime-probe", definition: { description: "Runtime probe", systemPrompt: "Runtime." } });
			try {
				const snapshot = discoverAgentSnapshot(project, "both", undefined, { includeChains: false, projectTrusted: false });
				const merged = mergeRuntimeAgents(pi, snapshot.effective, snapshot.effective.agents, { cwd: project, scope: snapshot.effective.scope, projectTrusted: false });
				assert.equal(merged.agents.some((agent) => agent.name === "runtime-probe"), true);
			} finally {
				registration.dispose();
			}
		}

		// A project's agentExcludeDirs cannot hide user agents either.
		writeJson(projectSettings, { subagents: { agentExcludeDirs: [userAgents] } });
		assert.equal(discoverAgents(project, "both").agents.some((agent) => agent.name === "probe"), false);
		assert.equal(discoverAgents(project, "both", undefined, untrusted).agents.some((agent) => agent.name === "probe"), true);
		assert.equal(discoverAgents(project, "both").agents.some((agent) => agent.name === "probe"), false);
	});
});

// Child-runner-only fault injection. Barriers are filesystem events, not elapsed waits.
import fs from "node:fs";
import path from "node:path";
import { syncBuiltinESMExports } from "node:module";

const root = process.env.RESULT_PUBLICATION_TEST_ROOT;
if (root) {
	const write = fs.writeFileSync;
	const rename = fs.renameSync;
	let resultAttempts = 0;
	let runningWritten = false;
	let statusDeferred = false;
	let asyncDir;
	let failedRecovery = false;
	const earlyTerminal = fs.existsSync(path.join(root, "early-terminal"));
	const barrier = (name, data) => {
		write(path.join(root, `${name}.tmp`), JSON.stringify(data));
		rename(path.join(root, `${name}.tmp`), path.join(root, name));
	};
	const full = () => Object.assign(new Error("injected result publication capacity failure"), { code: "ENOSPC" });
	fs.writeFileSync = function (file, data, ...args) {
		const target = String(file);
		if (path.basename(target).startsWith(".status.json.") && typeof data === "string") {
			const status = JSON.parse(data);
			asyncDir = path.dirname(target);
			if (!earlyTerminal && runningWritten && resultAttempts === 0) {
				statusDeferred = true;
				throw full();
			}
			if (status.state === "running") runningWritten = true;
		}
		if (target.includes(`${path.sep}result-pending${path.sep}`) && target.endsWith(".tmp")) {
			resultAttempts++;
			if (!fs.existsSync(path.join(root, "release"))) {
				if (resultAttempts >= 2) {
					const status = JSON.parse(fs.readFileSync(path.join(asyncDir, "status.json"), "utf8"));
					barrier("blocked.json", {
						state: status.state, statusDeferred,
						active: fs.existsSync(path.join(path.dirname(asyncDir), ".active-runs", path.basename(asyncDir))),
					});
				}
				throw full();
			}
			if (!failedRecovery && fs.existsSync(path.join(root, "fail-on-recovery"))) {
				failedRecovery = true;
				throw Object.assign(new Error("injected non-capacity publication failure"), { code: "EIO" });
			}
		}
		return write.call(this, file, data, ...args);
	};
	fs.renameSync = function (source, target) {
		const result = rename.call(this, source, target);
		if (!earlyTerminal && path.basename(String(target)) === "steer-inbox-closed.json") {
			// A request queued just before inbox closure is consumed during finalization.
			const dir = path.join(path.dirname(String(target)), "steer-requests");
			fs.mkdirSync(dir, { recursive: true });
			write(path.join(dir, "publication-steer.json"), JSON.stringify({ type: "steer", id: "publication-steer", ts: 1, message: "Late queued request", targetIndex: 0 }));
		}
		if (path.basename(String(target)) === "status.json") {
			const status = JSON.parse(fs.readFileSync(target, "utf8"));
			if (status.state === "complete" || status.state === "failed") barrier("terminal.json", status);
		}
		if (earlyTerminal && path.basename(String(target)) === "process-terminal-candidate.json") {
			const candidate = JSON.parse(fs.readFileSync(target, "utf8"));
			if (candidate.expectedWriters) barrier("drained.json", candidate);
		}
		return result;
	};
	syncBuiltinESMExports();
}

import * as fs from "node:fs";
import * as path from "node:path";
import { pathToFileURL } from "node:url";
import { writeAtomicJson } from "../../shared/atomic-json.ts";
import { acquireSessionLease } from "../shared/session-lease.ts";
import { readProcessTerminalCandidate, writeProcessTerminalCandidate, markProcessTerminalCandidateLeaseRelease } from "./process-terminal-candidate.ts";
import { persistRunnerStartupFailure } from "./runner-startup-failure.ts";
import { currentPidNamespaceScope } from "./pid-namespace.ts";
import type { DefaultChildSessionFactoryOptions } from "../shared/child-session.ts";
import type { SubagentRunConfig } from "./subagent-runner.ts";

export type { SubagentRunConfig } from "./subagent-runner.ts";

type ExecutionModule = {
	runConfiguredSubagentExecution(config: SubagentRunConfig, options?: DefaultChildSessionFactoryOptions): Promise<void>;
};

export interface RunnerBootstrapOptions extends DefaultChildSessionFactoryOptions {
	/** Test-only seam for proving that execution loading stays behind startup commit. */
	loadExecutionModule?: () => Promise<ExecutionModule>;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return Boolean(value) && typeof value === "object" && !Array.isArray(value);
}

function validateChildStep(value: unknown, field: string): void {
	if (!isRecord(value)) {
		throw new Error(`Invalid runner configuration: '${field}' must be an object.`);
	}
	if (typeof value.agent !== "string" || !value.agent) {
		throw new Error(`Invalid runner configuration: '${field}.agent' must be a non-empty string.`);
	}
	if (typeof value.task !== "string") {
		throw new Error(`Invalid runner configuration: '${field}.task' must be a string.`);
	}
	for (const requiredBoolean of ["inheritProjectContext", "inheritGlobalContext", "inheritSkills"] as const) {
		if (typeof value[requiredBoolean] !== "boolean") {
			throw new Error(`Invalid runner configuration: '${field}.${requiredBoolean}' must be a boolean.`);
		}
	}
}

function validateStep(value: unknown, index: number): void {
	const field = `steps[${index}]`;
	if (!isRecord(value)) {
		throw new Error(`Invalid runner configuration: '${field}' must be an object.`);
	}
	if ("expand" in value || "collect" in value) {
		if (!isRecord(value.expand)) {
			throw new Error(`Invalid runner configuration: '${field}.expand' must be an object.`);
		}
		if (!isRecord(value.collect)) {
			throw new Error(`Invalid runner configuration: '${field}.collect' must be an object.`);
		}
		validateChildStep(value.parallel, `${field}.parallel`);
		return;
	}
	if (Array.isArray(value.parallel)) {
		if (value.parallel.length === 0) {
			throw new Error(`Invalid runner configuration: '${field}.parallel' must not be empty.`);
		}
		value.parallel.forEach((step, childIndex) => validateChildStep(step, `${field}.parallel[${childIndex}]`));
		return;
	}
	validateChildStep(value, field);
}

export function validateSubagentRunConfig(value: unknown): asserts value is SubagentRunConfig {
	if (!isRecord(value)) {
		throw new Error("Invalid runner configuration: root must be an object.");
	}
	for (const field of ["id", "resultPath", "cwd", "asyncDir"] as const) {
		if (typeof value[field] !== "string" || !value[field]) {
			throw new Error(`Invalid runner configuration: '${field}' must be a non-empty string.`);
		}
	}
	if (typeof value.placeholder !== "string") {
		throw new Error("Invalid runner configuration: 'placeholder' must be a string.");
	}
	if (!Array.isArray(value.steps) || value.steps.length === 0) {
		throw new Error("Invalid runner configuration: 'steps' must be a non-empty array.");
	}
	value.steps.forEach(validateStep);
}

async function waitForStartupControl(controlPath: string, token: string, action: "ack" | "confirm" | "proceed", timeoutMs = 30_000): Promise<void> {
	const deadline = Date.now() + timeoutMs;
	while (Date.now() <= deadline) {
		if (fs.existsSync(controlPath)) {
			let payload: { action?: unknown; token?: unknown };
			try {
				payload = JSON.parse(fs.readFileSync(controlPath, "utf-8")) as { action?: unknown; token?: unknown };
			} catch (error) {
				throw new Error(`Failed to read runner startup control '${controlPath}': ${error instanceof Error ? error.message : String(error)}`);
			}
			if (payload.token !== token) {
				throw new Error("Runner startup control token does not match.");
			}
			if (payload.action === action) {
				return;
			}
			if (payload.action !== "ack" && payload.action !== "confirm" && payload.action !== "proceed") {
				throw new Error("Runner startup control action is invalid.");
			}
		}
		await new Promise((resolve) => setTimeout(resolve, 20));
	}
	throw new Error(`Timed out after ${timeoutMs}ms waiting for runner startup control '${action}'.`);
}

/** Owns startup authorization and any revival lease across dynamically loaded execution. */
export async function runConfiguredSubagent(rawConfig: unknown, options: RunnerBootstrapOptions = {}): Promise<void> {
	validateSubagentRunConfig(rawConfig);
	const config = rawConfig;
	let lease: ReturnType<typeof acquireSessionLease> | undefined;
	let startupCommitted = config.revivalLease === undefined && config.launchBarrierToken === undefined;
	let executionLoaded = false;
	const startupPath = path.join(config.asyncDir, "runner-startup.json");
	const startupAckPath = path.join(config.asyncDir, "runner-startup-ack.json");
	const startupConfirmPath = path.join(config.asyncDir, "runner-startup-confirm.json");
	const startupProceedPath = path.join(config.asyncDir, "runner-startup-proceed.json");
	const releaseOnExit = (): void => {
		try {
			lease?.release();
		} catch {
			// Dead-owner leases are reclaimed on the next revival.
		}
	};
	process.once("exit", releaseOnExit);
	try {
		if (config.launchBarrierToken) {
			// Behind a launcher the parent only knows the wrapper's pid; report this runner's own identity first.
			if (config.launcher) writeAtomicJson(startupPath, { state: "identified", token: [REDACTED], pid: process.pid, pidNamespaceScope: currentPidNamespaceScope() });
			await waitForStartupControl(startupProceedPath, config.launchBarrierToken, "proceed");
			startupCommitted = true;
			try {
				fs.rmSync(startupProceedPath, { force: true });
			} catch {
				// Best effort after commit.
			}
		} else if (config.revivalLease) {
			lease = acquireSessionLease(config.revivalLease);
			config.revivalLeaseToken = [REDACTED];
			writeAtomicJson(startupPath, { state: "ready", token: [REDACTED], pid: process.pid, owner: lease.owner, ...(config.launcher ? { pidNamespaceScope: currentPidNamespaceScope() } : {}) });
			await waitForStartupControl(startupAckPath, lease.owner.token, "ack");
			writeAtomicJson(startupPath, { state: "acknowledged", token: [REDACTED], pid: process.pid });
			await waitForStartupControl(startupConfirmPath, lease.owner.token, "confirm");
			writeAtomicJson(startupPath, { state: "confirmed", token: [REDACTED], pid: process.pid });
			await waitForStartupControl(startupProceedPath, lease.owner.token, "proceed");
			startupCommitted = true;
			for (const controlPath of [startupAckPath, startupConfirmPath, startupProceedPath]) {
				try {
					fs.rmSync(controlPath, { force: true });
				} catch {
					// Best effort after commit.
				}
			}
		}
		if (lease) {
			// Persist token identity before the heavy import so an import rejection
			// still leaves the parent enough evidence to prove lease release.
			const candidate = readProcessTerminalCandidate(config.asyncDir);
			if (candidate) {
				writeProcessTerminalCandidate(config.asyncDir, {
					...candidate,
					sessionFile: config.revivalLease?.sessionFile,
					revivalLeaseToken: [REDACTED],
				});
			}
		}
		const { loadExecutionModule, ...executionOptions } = options;
		const testExecutionModule = process.env.PI_SUBAGENTS_TEST_RUNNER_EXECUTION_MODULE;
		const execution = await (loadExecutionModule?.() ?? (testExecutionModule ? import(testExecutionModule) : import("./subagent-runner.ts")));
		executionLoaded = true;
		await execution.runConfiguredSubagentExecution(config, executionOptions);
	} catch (error) {
		if (!startupCommitted) {
			try {
				writeAtomicJson(startupPath, { state: "error", pid: process.pid, error: error instanceof Error ? error.message : String(error) });
			} catch {
				// The parent will time out and terminate if startup evidence cannot be written.
			}
		} else if (!executionLoaded) {
			try {
				persistRunnerStartupFailure({
					asyncDir: config.asyncDir,
					runId: config.id,
					runnerProcessInstanceId: config.runnerProcessInstanceId ?? "unknown-runner-instance",
					message: `Subagent runner startup failed: ${error instanceof Error ? error.message : String(error)}`,
					...(config.sessionId ? { sessionId: config.sessionId } : {}),
					...(config.completionOwnerId ? { completionOwnerId: config.completionOwnerId } : {}),
					candidate: {
						...(config.revivalLease?.sessionFile ? { sessionFile: config.revivalLease.sessionFile } : {}),
						...(config.revivalLeaseToken ? { revivalLeaseToken: [REDACTED] } : {}),
					},
				});
			} catch (persistenceError) {
				console.error("Failed to persist runner startup failure:", persistenceError);
			}
		}
		throw error;
	} finally {
		process.off("exit", releaseOnExit);
		if (lease) {
			let acknowledged = false;
			try {
				acknowledged = lease.release();
			} catch (error) {
				console.error("Failed to release session revival lease:", error);
			}
			try {
				markProcessTerminalCandidateLeaseRelease(config.asyncDir, lease.owner.token, acknowledged);
			} catch (error) {
				console.error("Failed to record session revival lease release:", error);
			}
		}
	}
}

function startConfiguredSubagent(config: unknown): void {
	runConfiguredSubagent(config).then(
		() => process.exit(0),
		(error) => {
			console.error("Subagent runner error:", error);
			process.exit(1);
		},
	);
}

function monitorTestParent(): void {
	const parentPid = Number(process.env.PI_SUBAGENTS_TEST_PARENT_PID);
	if (!Number.isSafeInteger(parentPid) || parentPid <= 0 || parentPid === process.pid) {
		return;
	}
	const check = () => {
		try {
			process.kill(parentPid, 0);
		} catch {
			process.exit(1);
		}
	};
	check();
	setInterval(check, 250).unref();
}

const isRunnerEntrypoint = Boolean(process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href);
if (isRunnerEntrypoint) {
	monitorTestParent();
	const configArg = process.argv[2];
	if (configArg) {
		try {
			const config = JSON.parse(fs.readFileSync(configArg, "utf-8")) as unknown;
			try {
				fs.unlinkSync(configArg);
			} catch {
				// Temp-config cleanup is best effort.
			}
			startConfiguredSubagent(config);
		} catch (error) {
			console.error("Subagent runner error:", error);
			process.exit(1);
		}
	} else {
		let input = "";
		process.stdin.setEncoding("utf-8");
		process.stdin.on("data", (chunk) => {
			input += chunk;
		});
		process.stdin.on("end", () => {
			try {
				startConfiguredSubagent(JSON.parse(input) as unknown);
			} catch (error) {
				console.error("Subagent runner error:", error);
				process.exit(1);
			}
		});
	}
}

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { compactForegroundResult, extractToolArgsPreview } from "../../src/shared/utils.ts";
import { formatToolCall } from "../../src/shared/formatters.ts";

describe("foreground tool-call compaction", () => {
	it("stores compact tool-call summaries instead of raw message payloads", () => {
		const result = compactForegroundResult({
			agent: "tester",
			task: "run checks",
			exitCode: 0,
			messages: [{
				role: "assistant",
				content: [{
					type: "toolCall",
					name: "write",
					arguments: {
						path: "/tmp/report.md",
						content: "x".repeat(50_000),
					},
				}],
			}],
			usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, turns: 0 },
		});

		assert.equal(result.messages, undefined);
		assert.deepEqual(result.toolCalls, [{
			text: "write /tmp/report.md",
			expandedText: "write /tmp/report.md",
		}]);
	});

	it("keeps expanded generic tool-call previews bounded", () => {
		const collapsed = formatToolCall("custom", { payload: "x".repeat(500) });
		const expanded = formatToolCall("custom", { payload: "x".repeat(500) }, true);

		assert.ok(expanded.length > collapsed.length);
		assert.ok(expanded.length < 200);
	});

	it("does not keep an empty toolCalls array after compaction", () => {
		const result = compactForegroundResult({
			agent: "tester",
			task: "run checks",
			exitCode: 0,
			messages: [],
			usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, cost: 0, turns: 0 },
		});

		assert.equal(result.toolCalls, undefined);
	});

	it("keeps live tool argument previews on one terminal line", () => {
		const preview = extractToolArgsPreview({
			command: "set +e\r\n\t\x1b[31mrun\x1b[0m \x1b]0;title\x07now\u0000",
		});

		assert.equal(preview, "set +e run now");
		assert.doesNotMatch(preview, /[\r\n\t\x1b]/);
	});

	it("keeps completed bash tool-call previews on one terminal line", () => {
		const preview = formatToolCall("bash", { command: "first\n\x1b[32msecond\x1b[0m" });

		assert.equal(preview, "$ first second");
		assert.doesNotMatch(preview, /[\r\n\t\x1b]/);
	});

	it("does not split surrogate pairs when truncating previews", () => {
		const preview = extractToolArgsPreview({ command: "😀".repeat(31) });

		assert.equal(preview, `${"😀".repeat(28)}...`);
		assert.doesNotMatch(preview, /[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/u);
		assert.equal(extractToolArgsPreview({ command: `safe\ud800tail\udc00end` }), "safe tail end");
	});

	it("normalizes fallback argument keys before display", () => {
		const preview = extractToolArgsPreview({ "bad\r\n\t\x1b[31mkey\x1b[0m\u0000": "value" });

		assert.equal(preview, "bad key=value");
		assert.doesNotMatch(preview, /[\u0000-\u001f\u007f-\u009f]/);
	});

	it("discards terminal string payloads while preserving readable suffixes", () => {
		for (const control of ["\x1b]0;title\x07", "\x1bPpayload\x1b\\", "\x9d0;title\x9c"]) {
			assert.equal(extractToolArgsPreview({ command: `before${control}after` }), "before after");
		}
	});

	it("formats array-based web search previews clearly", () => {
		assert.equal(
			extractToolArgsPreview({
				queries: ["Chrome native messaging manifest path macOS", "Chromium native messaging path macOS"],
				workflow: "none",
			}),
			"Chrome native messaging manifest path macOS (+1 more)",
		);
	});

	it("formats fetch_content urls clearly", () => {
		assert.equal(
			extractToolArgsPreview({
				urls: ["https://developer.chrome.com/docs/extensions/develop/concepts/native-messaging", "https://example.com/backup"],
			}),
			"https://developer.chrome.com/docs/extensions/develop/conc...",
		);
	});

	it("falls back to generic array previews", () => {
		assert.equal(
			extractToolArgsPreview({ ids: ["run-a", "run-b", "run-c"] }),
			"ids=run-a (+2 more)",
		);
	});
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { randomUUID } from "node:crypto";
import { createBashToolDefinition, type ExtensionContext } from "@earendil-works/pi-coding-agent";
import { commandAction } from "../../src/runs/foreground/command-action.ts";
import { createChildCommandRuntime } from "../../src/runs/shared/child-commands.ts";
import { supervisorChannelDir } from "../../src/runs/shared/child-tool-plan.ts";
import type { SubagentState } from "../../src/shared/types.ts";

const ctx = { sessionManager: { getSessionId: () => "session-1", getSessionFile: () => undefined } } as ExtensionContext;
function liveState(runId: string): SubagentState {
	const state = { currentSessionId: "session-1", foregroundControls: new Map(), foregroundRuns: new Map() } as SubagentState;
	state.currentSessionId = "session-1";
	state.foregroundControls.set(runId, {
		runId, sessionId: "session-1", mode: "parallel", startedAt: Date.now(), updatedAt: Date.now(),
		activeChildren: new Map([0, 1].map((index) => [index, { index, agent: "worker", startedAt: Date.now(), updatedAt: Date.now() }])),
	});
	return state;
}

async function until(check: () => boolean, label: string): Promise<void> {
	const deadline = Date.now() + 15_000;
	while (!check()) {
		if (Date.now() > deadline) throw new Error(`Timed out waiting for ${label}`);
		await new Promise((resolve) => setTimeout(resolve, 20));
	}
}
function exited(pid: number): boolean {
	try { process.kill(pid, 0); return false; }
	catch (error) { return (error as NodeJS.ErrnoException).code === "ESRCH"; }
}

describe("supervisor command actions", () => {
	for (const kind of ["foreground", "async"] as const) {
		it(`targets one command in a ${kind} child`, async () => {
			const runId = `command-action-${randomUUID()}`;
			const channel = supervisorChannelDir(runId, "worker", 1);
			const commands = createChildCommandRuntime(channel);
			const dir = fs.mkdtempSync(path.join(os.tmpdir(), "pi-command-action-"));
			const state = liveState(runId);
			const target = kind === "foreground" ? { kind, id: runId } : { kind, id: runId, location: { resolvedId: runId, asyncDir: dir, resultPath: null } };
			if (kind === "async") fs.writeFileSync(path.join(dir, "status.json"), JSON.stringify({ runId, sessionId: "session-1", state: "running", steps: [{ agent: "worker", status: "running" }, { agent: "worker", status: "running" }] }));
			// On Windows, Pi ends a cancelled command with a taskkill it does not await.
			const pidFile = path.join(dir, "command.pid");
			fs.writeFileSync(path.join(dir, "hold.cjs"), `require("node:fs").writeFileSync(${JSON.stringify(pidFile)}, String(process.pid)); setTimeout(() => {}, 10_000);`);
			let pid: number | undefined;
			try {
				await commands.wrap(createBashToolDefinition(dir)).execute("selected-command", { command: `${JSON.stringify(process.execPath)} hold.cjs`, yieldTimeMs: 0 }, undefined, undefined, ctx);
				await until(() => fs.existsSync(pidFile) && fs.readFileSync(pidFile, "utf8").length > 0, "the command to start");
				pid = Number(fs.readFileSync(pidFile, "utf8"));
				await assert.rejects(commandAction({ state, target, operation: "cancel", toolCallId: "selected-command" }), /explicit child index/);
				await assert.rejects(commandAction({ state, target, operation: "cancel", index: 1 }), /exact toolCallId/);
				const result = await commandAction({ state, target, operation: "status", index: 1, toolCallId: "selected-command" });
				assert.equal(result.details.commands?.[0].state, "yielded");
				state.currentSessionId = "different-session";
				await assert.rejects(commandAction({ state, target, operation: "cancel", index: 1, toolCallId: "selected-command" }), /not owned by this session/);
				state.currentSessionId = "session-1";
				await commandAction({ state, target, operation: "cancel", index: 1, toolCallId: "selected-command" });
				await commands.shutdown();
				const terminal = await commandAction({ state, target, operation: "status", index: 1 });
				assert.equal(terminal.details.commands?.[0].state, "cancelled");
			} finally {
				await commands.shutdown();
				if (pid !== undefined) await until(() => exited(pid!), `command process ${pid} to exit`);
				fs.rmSync(channel, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 }); fs.rmSync(dir, { recursive: true, force: true, maxRetries: 5, retryDelay: 50 });
			}
		});
	}
});

