	const asyncDir = path.join(root, "run-123");
	fs.mkdirSync(asyncDir, { recursive: true });
	const status: AsyncStatus = {
		runId: "run-123",
		mode: "single",
		state: "completed",
		startedAt: Date.now() - 1_000,
		cwd: root,
		steps: [{ agent: "worker", status: "completed", recentOutput: ["done"] }],
