		let receivedLimits: unknown;
		let recoveryStarted = false;
		let recoveryCommitted = false;
		let request: SteerRequest | undefined;
		let routed: AsyncStatus | undefined;
		try {
			const action = steerAsyncRun({
				state: createState(),
				runId,
				message: "correct course",
				location: { asyncDir },
				ackTimeoutMs: 250,
				recoveryTimeoutMs: 1_000,
				kill: () => true,
				onRequestQueued: (requestPath) => {
					request = JSON.parse(fs.readFileSync(requestPath, "utf-8")) as SteerRequest;
					routed = runningStatus(runId);
					projectRequest(routed, request, ["routed"]);
					writeStatus(asyncDir, routed);
				},
				onRecoveryCommitted: () => {
					recoveryCommitted = true;
					assert.ok(request);
					assert.ok(routed);
					writeStatus(asyncDir, {
						...routed,
						state: "paused",
						endedAt: Date.now(),
						toolBudget: { soft: 8, hard: 12, block: ["read"], toolCount: 9, outcome: "soft-reached" },
						steps: [{ ...routed.steps![0]!, status: "paused", sessionFile }],
					});
				},
				recover: async (limits) => {
					recoveryStarted = true;
					const paused = JSON.parse(fs.readFileSync(path.join(asyncDir, "status.json"), "utf-8")) as AsyncStatus;
					assert.equal(paused.state, "paused");
					assert.equal(typeof paused.endedAt, "number");
					receivedLimits = limits;
					return successResult("replacement");
				},
			});
			const result = await action;
			assert.equal(result.isError, undefined);
			assert.equal(result.details.steering?.state, "recovered");
			assert.match(result.content[0]!.text, /Message sent:\n```text\ncorrect course\n```/);
			assert.equal(result.details.steering?.replacementRunId, "replacement");
			const limits = receivedLimits as { timeoutMs: number; absoluteDeadlineAt: number; toolBudget: unknown };
			assert.ok(limits.timeoutMs > 0 && limits.timeoutMs <= 10_000);
			assert.ok(limits.absoluteDeadlineAt >= Date.now());
			assert.deepEqual({ toolBudget: limits.toolBudget }, {
				toolBudget: { hard: 3, block: ["read"] },
			});
			const persisted = JSON.parse(fs.readFileSync(path.join(asyncDir, "status.json"), "utf-8")) as AsyncStatus;
			assert.equal(persisted.steering?.recent[0]?.targets[0]?.state, "recovered");
			assert.equal(persisted.steps?.[0]?.steering?.recent[0]?.targets[0]?.state, "recovered");
		} finally {
			removeAsyncDir(asyncDir);
		}
	});

	it("leaves a single run paused when no session can be revived", async () => {
		const runId = `steer-no-session-${Date.now().toString(36)}`;
		const asyncDir = path.join(ASYNC_DIR, runId);
		writeStatus(asyncDir, runningStatus(runId));
		writePrivateAtomicJson(path.join(asyncDir, "recovery-descriptor.json"), recoveryDescriptor(runId));
		let recovered = false;
		let recoveryCommitted = false;
		let routed: AsyncStatus | undefined;
		try {
			const action = steerAsyncRun({
				state: createState(), runId, message: "correct course", location: { asyncDir }, ackTimeoutMs: 250, recoveryTimeoutMs: 1_000, kill: () => true,
				onRequestQueued: (requestPath) => {
					const request = JSON.parse(fs.readFileSync(requestPath, "utf-8")) as SteerRequest;
					routed = runningStatus(runId);
					projectRequest(routed, request, ["failed"]);
					writeStatus(asyncDir, routed);
				},
				onRecoveryCommitted: () => {
					recoveryCommitted = true;
					if (routed) writeStatus(asyncDir, { ...routed, state: "paused", endedAt: Date.now(), steps: [{ ...routed.steps![0]!, status: "paused" }] });
				},
				recover: async () => { recovered = true; return successResult("replacement"); },
			});
			const result = await action;
			assert.ok(recoveryCommitted);
			assert.ok(routed);
			assert.equal(result.isError, true);
			assert.equal(recovered, false);
			assert.match(result.content[0]!.text, /no persisted child session|does not have a persisted session file/i);
		} finally {
			removeAsyncDir(asyncDir);
		}
	});

	it("never auto-interrupts a nested single run", async () => {
		const runId = `steer-nested-${Date.now().toString(36)}`;
		const asyncDir = path.join(ASYNC_DIR, runId);
		const initial = runningStatus(runId);
		initial.isNested = true;
		writeStatus(asyncDir, initial);
		let interrupted = false;
		let recovered = false;
		try {
			const action = steerAsyncRun({
				state: createState(), runId, message: "correct course", location: { asyncDir }, ackTimeoutMs: 25,
				kill: (_pid, signal) => { if (signal !== 0) interrupted = true; return true; },
				recover: async () => { recovered = true; return successResult("replacement"); },
			});
			const request = await readRequest(asyncDir);
			const routed = runningStatus(runId);
			routed.isNested = true;
			projectRequest(routed, request, ["routed"]);
			writeStatus(asyncDir, routed);
			const result = await action;
			assert.equal(result.details.steering?.state, "pending");
			assert.equal(interrupted, false);
			assert.equal(recovered, false);
			assert.equal(fs.existsSync(interruptRequestPath(asyncDir)), false);
		} finally {
			removeAsyncDir(asyncDir);
		}
	});

	it("reports partial multi-child delivery without interrupting the run", async () => {
		const runId = `steer-partial-${Date.now().toString(36)}`;
		const asyncDir = path.join(ASYNC_DIR, runId);
		writeStatus(asyncDir, runningStatus(runId, "parallel", 2));
		let killed = false;
		try {
			const action = steerAsyncRun({ state: createState(), runId, message: "correct course", location: { asyncDir }, ackTimeoutMs: 500, kill: (_pid, signal) => { if (signal !== 0) killed = true; return true; } });
			const request = await readRequest(asyncDir);
			assert.deepEqual(request.targetIndexes, [0, 1]);
			const status = runningStatus(runId, "parallel", 2);
			projectRequest(status, request, ["delivered", "failed"]);
			writeStatus(asyncDir, status);
			const result = await action;
			assert.equal(result.isError, true);
			assert.equal(result.details.steering?.state, "partial");
			assert.equal(killed, false);
			assert.equal(fs.existsSync(interruptRequestPath(asyncDir)), false);
		} finally {
			removeAsyncDir(asyncDir);
		}
	});
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import {
	permissionArgsPreview,
	permissionDecision,
	resolvePermissionRules,
	validatePermissionConfig,
	validatePermissionRules,
} from "../../src/runs/shared/permissions.ts";

describe("native child permissions", () => {
	it("defaults every unconfigured tool and bash to pass-through", () => {
		assert.equal(permissionDecision(undefined, "write"), "allow");
		assert.equal(permissionDecision({ write: "deny" }, "unknown_tool"), "allow");
		assert.equal(permissionDecision({ write: "deny" }, "bash"), "allow");
		assert.equal(resolvePermissionRules(), undefined);
	});

	it("merges explicit global and agent rules while removing explicit allow rules", () => {
		assert.deepEqual(resolvePermissionRules(
			{ rules: { write: "ask", edit: "deny" } },
			{ write: "allow", read: "deny" },
		), { edit: "deny", read: "deny" });
	});

	it("rejects bash and coordination-tool rules", () => {
		assert.throws(() => validatePermissionRules({ bash: "ask" }, "permissions"), /pi-guard/);
		assert.throws(() => validatePermissionRules({ contact_supervisor: "deny" }, "permissions"), /reserved for child coordination/);
		assert.throws(() => validatePermissionConfig({ rules: { write: "sometimes" } }), /allow, ask, or deny/);
	});

	it("redacts bounded argument previews", () => {
		const preview = permissionArgsPreview({ token: "[REDACTED]", content: `Bearer abcdefghijklmnop ${"x".repeat(3000)}` });
		assert.doesNotMatch(preview, /secret-value|abcdefghijklmnop/);
		assert.ok(Buffer.byteLength(preview) <= 2048);

		const multibytePreview = permissionArgsPreview({ content: Array.from({ length: 10 }, () => "😀".repeat(300)) });
		assert.ok(Buffer.byteLength(multibytePreview, "utf-8") <= 2048);
		assert.doesNotMatch(multibytePreview, /�/);
		assert.match(multibytePreview, /…$/);
	});
});

import assert from "node:assert/strict";
import { describe, it } from "node:test";
import { resolveAuthorityDecision, validateAuthorityPolicy } from "../../src/policy/authority.ts";

describe("authority policy", () => {
	it("uses conservative cleanup and spawn defaults without obstructing normal control", () => {
		assert.equal(resolveAuthorityDecision({ action: "discardWorktree" }), "confirm");
		assert.equal(resolveAuthorityDecision({ action: "destructiveCleanup" }), "confirm");
		assert.equal(resolveAuthorityDecision({ action: "spawnBudgetGrant" }), "confirm");
		assert.equal(resolveAuthorityDecision({ action: "scheduleCreate" }), "auto");
		assert.equal(resolveAuthorityDecision({ action: "stopRun" }), "auto");
		assert.equal(resolveAuthorityDecision({ action: "steerRun" }), "auto");
	});

	it("confirms project panes that spawn an unchecked host and leaves plugin-gated inspectors automatic", () => {
		assert.equal(resolveAuthorityDecision({ action: "inspectorOpen" }), "auto");
		assert.equal(resolveAuthorityDecision({ action: "projectOpen" }), "confirm");
		const policy = validateAuthorityPolicy({ inspectorOpen: "forbid", projectOpen: "auto" });
		assert.equal(resolveAuthorityDecision({ action: "inspectorOpen", policy }), "forbid");
		assert.equal(resolveAuthorityDecision({ action: "projectOpen", policy }), "auto");
	});

	it("accepts only fixed actions and decisions", () => {
		const policy = validateAuthorityPolicy({ discardWorktree: "forbid", stopRun: "confirm" });
		assert.equal(resolveAuthorityDecision({ action: "discardWorktree", policy }), "forbid");
		assert.equal(resolveAuthorityDecision({ action: "stopRun", policy }), "confirm");
		assert.throws(() => validateAuthorityPolicy({ mergePullRequest: "auto" }), /unknown/);
		assert.throws(() => validateAuthorityPolicy({ discardWorktree: "sometimes" }), /auto.*confirm.*forbid/);
	});
});

import assert from "node:assert/strict";
import * as os from "node:os";
import * as path from "node:path";
import { describe, it } from "node:test";
import { createSubagentExecutor } from "../../src/runs/foreground/subagent-executor.ts";
import type { AuthorityPolicyConfig, SubagentState } from "../../src/shared/types.ts";

function createState(): SubagentState {
	return {
		baseCwd: "",
		currentSessionId: null,
		asyncJobs: new Map(),
		foregroundRuns: new Map(),
		foregroundControls: new Map(),
		lastForegroundControlId: null,
		pendingForegroundControlNotices: new Map(),
		cleanupTimers: new Map(),
		lastUiContext: null,
		poller: null,
		completionSeen: new Map(),
		watcher: null,
		watcherRestartTimer: null,
		resultFileCoalescer: { schedule: () => false, clear: () => {} },
	};
}

function createExecutor(authorityPolicy?: AuthorityPolicyConfig, childSafe = false) {
	return createSubagentExecutor({
		pi: { events: { emit() {}, on() { return () => {}; } }, getSessionName() { return "parent"; } } as any,
		state: createState(),
		config: { maxSubagentDepth: 2, control: {}, intercomBridge: {}, ...(authorityPolicy ? { authorityPolicy } : {}) } as any,
		...(childSafe ? { allowMutatingManagementActions: false } : {}),
		asyncByDefault: false,
		tempArtifactsDir: os.tmpdir(),
		getSubagentSessionRoot: () => os.tmpdir(),
		expandTilde: (value) => value,
		discoverAgents: () => ({ agents: [] }),
	});
}

function ctx(ui?: { confirm: () => Promise<boolean> }) {
	return {
		cwd: os.tmpdir(),
		hasUI: Boolean(ui),
		...(ui ? { ui } : {}),
		sessionManager: { getSessionId() { return "session"; }, getSessionFile() { return null; } },
		modelRegistry: { getAvailable() { return []; } },
	} as any;
}

async function run(action: string, policy?: AuthorityPolicyConfig, ui?: { confirm: () => Promise<boolean> }, childSafe = false): Promise<{ text: string; isError?: boolean }> {
	const result = await createExecutor(policy, childSafe).execute(action, { action }, new AbortController().signal, undefined, ctx(ui));
	return { text: result.content.find((entry) => entry.type === "text")?.text ?? "", ...(result.isError === undefined ? {} : { isError: result.isError }) };
}

// `project.open` spawns the Herdr CLI, so point the client at a path that cannot
// exist whenever the policy is expected to let the action through.
async function withoutHerdr<T>(body: () => Promise<T>): Promise<T> {
	const previous = process.env.HERDR_BIN;
	process.env.HERDR_BIN = path.join(os.tmpdir(), "pi-subagents-absent-herdr-binary");
	try {
		return await body();
	} finally {
		if (previous === undefined) delete process.env.HERDR_BIN;
		else process.env.HERDR_BIN = previous;
	}
}

describe("inspector and project pane authority policy", () => {
	it("requires confirmation for project.open and fails closed without an interactive UI", async () => {
		const { text, isError } = await run("project.open");

		assert.equal(isError, true);
		assert.match(text, /requires user confirmation for action 'project\.open'/);
	});

	it("cancels project.open when the operator declines the confirmation", async () => {
		let asked = 0;
		const { text } = await run("project.open", undefined, { confirm: async () => { asked += 1; return false; } });

		assert.equal(asked, 1);
		assert.match(text, /Action 'project\.open' canceled; authority was not granted\./);
	});

	it("forbids project.open outright when the policy says so", async () => {
		const { text, isError } = await run("project.open", { projectOpen: "forbid" });

		assert.equal(isError, true);
		assert.match(text, /Authority policy forbids action 'project\.open'\./);
	});

	it("runs project.open unprompted when the policy opts back in to auto", async () => {
		const { text } = await withoutHerdr(() => run("project.open", { projectOpen: "auto" }));

		assert.doesNotMatch(text, /Authority policy/);
		assert.match(text, /Herdr/);
	});

	it("leaves inspector.open automatic by default so the plugin gate still decides", async () => {
		const { text } = await run("inspector.open");

		assert.doesNotMatch(text, /Authority policy/);
		assert.match(text, /Inspector actions require id or dir/);
	});

	it("forbids inspector.open when the policy says so", async () => {
		const { text, isError } = await run("inspector.open", { inspectorOpen: "forbid" });

		assert.equal(isError, true);
		assert.match(text, /Authority policy forbids action 'inspector\.open'\./);
	});

	it("requires confirmation for inspector.open when the operator opts in", async () => {
		const { text, isError } = await run("inspector.open", { inspectorOpen: "confirm" });

		assert.equal(isError, true);
		assert.match(text, /requires user confirmation for action 'inspector\.open'/);
	});

	it("refuses project.open in child-safe fanout mode without prompting for authority", async () => {
		let asked = 0;
		const { text, isError } = await run("project.open", undefined, { confirm: async () => { asked += 1; return true; } }, true);

		assert.equal(asked, 0);
		assert.equal(isError, true);
		assert.match(text, /Action 'project\.open' is not available from child-safe subagent fanout mode\./);
	});

	it("reports the child-safe restriction for inspector.open rather than the policy that also forbids it", async () => {
		const { text, isError } = await run("inspector.open", { inspectorOpen: "forbid" }, undefined, true);

		assert.equal(isError, true);
		assert.match(text, /Action 'inspector\.open' is not available from child-safe subagent fanout mode\./);
	});

	it("refuses schedule.create in child-safe fanout mode without prompting for authority", async () => {
		let asked = 0;
		const { text, isError } = await run("schedule.create", { scheduleCreate: "confirm" }, { confirm: async () => { asked += 1; return true; } }, true);

		assert.equal(asked, 0);
		assert.equal(isError, true);
		assert.match(text, /Action 'schedule\.create' is not available from child-safe subagent fanout mode\./);
	});
});

